        return { build_number: 3, build_url: 'http://bitrise/b3' };
    };
    globals.bitrise_abort_build = function(args) {
        rec.calls.push({ op: 'bitrise_abort_build', args: args });
        if (mocks.bitriseAbortBuild) return mocks.bitriseAbortBuild(args);
        return {};
    };
    return globals;
}
```
CC: 1 + 3 ifs = 4.

Then:
```js
function loadTaModule(mocks) {
    return loadModule('js/triggerBitriseTestAutomation.js', makeRequire({
        './configLoader.js': makeTaConfigLoader(mocks.rec, mocks),
        './config.js': configModule,
        './common/trackers.js': makeTaTracker(mocks.rec, mocks.trackerApi)
    }), makeTaGlobals(mocks.rec, mocks));
}
```
CC = 1. 

Also the `||` in `var trackerApi = mocks.trackerApi || {};` adds a branch — move it into makeTaTracker's `var api = trackerApi || {}` (already counted).

Now — nested functions inside makeTaTracker: do getIssue/searchIssues etc. register as separate named functions in crap4js? They're anonymous function expressions assigned to object properties — typically not counted as separate functions, but their branches may count toward enclosing function's CC (as was the case with loadTaModule). So makeTaTracker CC = 1 + ternaries in getIssue, searchIssues, postComment, removeLabel = 5. Good.

Note moveToStatusOrMark has no branch. Good.

